using System;

namespace wb.AdBlock
{
    /// <summary>
    /// Represents a user-created cosmetic filter rule generated by the uBlock Dropper (element picker)
    /// or manually created in the Manage Blocked Elements list.
    /// Format: domain.com##selector (domain-scoped) or ##selector (global).
    /// </summary>
    public class CustomFilterRule
    {
        public string Id { get; set; }
        public string Domain { get; set; }
        public string Selector { get; set; }
        public string RawRule { get; set; }
        public DateTime CreatedAtUtc { get; set; }

        public CustomFilterRule()
        {
            Id = Guid.NewGuid().ToString("N");
            CreatedAtUtc = DateTime.UtcNow;
            Domain = string.Empty;
            Selector = string.Empty;
            RawRule = string.Empty;
        }

        public CustomFilterRule(string domain, string selector)
        {
            Id = Guid.NewGuid().ToString("N");
            CreatedAtUtc = DateTime.UtcNow;
            Domain = !string.IsNullOrEmpty(domain) ? domain.Trim().ToLowerInvariant() : string.Empty;

            string s = selector != null ? selector.Trim() : string.Empty;
            if (s.StartsWith("##", StringComparison.Ordinal))
            {
                s = s.Substring(2).Trim();
            }
            Selector = s;

            if (string.IsNullOrEmpty(Domain))
            {
                RawRule = "##" + Selector;
            }
            else
            {
                RawRule = Domain + "##" + Selector;
            }
        }
    }
}
